const item = $input.first();
const msg = item.json.message;
const chatId = String(msg.chat.id);
const mime = msg.document?.mime_type || '';
const fname = msg.document?.file_name || '';
const isExcel = !!(mime.includes('spreadsheetml') || fname.toLowerCase().endsWith('.xlsx'));
const isPdf = !!(mime === 'application/pdf' || fname.toLowerCase().endsWith('.pdf'));
if (!isExcel && !isPdf) throw new Error('Send Excel (.xlsx) or PDF only.');
return [{ json: { chatId, isExcel, isPdf, fileName: fname || 'file' }, binary: item.binary || {} }];

const chatId = $('Validate Input').first().json.chatId;
const allRows = $input.all().map(i => i.json);
const productsJson = allRows.map(r => JSON.stringify(r)).join('\n');
return [{ json: { chatId, products_json: productsJson, total_rows: allRows.length } }];

const tgItem = $('Telegram Message').first();
const binary = tgItem.binary?.data;
if (!binary || !binary.data) {
  throw new Error('No PDF binary found. Make sure Telegram Trigger has download enabled.');
}
const fileName = $('Validate Input').first().json.fileName || 'document.pdf';
return [{ json: { fileName, base64: binary.data, mimeType: binary.mimeType || 'application/pdf' } }];

const content = $input.first().json.choices?.[0]?.message?.content || '';
if (!content) throw new Error('GPT returned empty response from PDF extraction.');

const clean = String(content).replace(/```json|```/gi, '').trim();
let products;
try { products = JSON.parse(clean); } catch (e) {
  throw new Error('Could not parse GPT response as JSON: ' + e.message + ' | Response: ' + clean.substring(0, 200));
}
if (!Array.isArray(products)) {
  throw new Error('GPT did not return a JSON array.');
}
if (products.length === 0) {
  throw new Error('No products found in the PDF.');
}

return products.map(p => ({ json: { Name: String(p.Name || p.name || '').trim(), SKU: String(p.SKU || p.sku || p.code || '').trim(), Price: parseFloat(p.Price || p.price || 0) || 0, Brand: String(p.Brand || p.brand || '').trim() } }));

const raw = $input.first().json.output || '';
const clean = String(raw).replace(/```json|```/gi,'').trim();
let rows; try { rows = JSON.parse(clean); } catch(e) { return [{ json:{error:e.message} }]; }
if (!Array.isArray(rows)) return [{ json:{error:'not array'} }];
const chatId = $('Validate Input').first().json.chatId;
return rows.map(r => { const cid = parseInt(String(r.Category_ID??0),10); return { json: { SKU: String(r.SKU||'').trim(), Product_Name: String(r.Product_Name||r.Name||'').trim(), Category: String(r.Category||''), categ_id: cid>0?cid:null, category_id_ready: cid>0, Brand: String(r.Brand||''), list_price: parseFloat(r.list_price||0)||0, chatId } }; });

const products = $input.all().map(i => i.json);
const skus = products.map(p => String(p.SKU || '').trim()).filter(s => s.length > 0);
return [{ json: { skus_csv: skus.join(','), sku_count: skus.length, total_products: products.length } }];

const products = $('Parse AI Output').all().map(i => i.json);
const odooResults = $input.all().map(i => i.json).filter(r => r && r.id);

const skuToOdooId = {};
odooResults.forEach(r => {
  if (r.default_code) skuToOdooId[String(r.default_code).toLowerCase()] = r.id;
});

return products.map(product => {
  const sku = String(product.SKU || '').trim();
  const productName = String(product.Product_Name || '').trim();
  const categId = parseInt(String(product.categ_id || ''), 10);
  const categoryReady = Number.isInteger(categId) && categId > 0;
  const odooIdFound = sku ? (skuToOdooId[sku.toLowerCase()] || null) : null;
  const skuFoundInOdoo = Boolean(odooIdFound);

  let duplicateCheck, notes;
  if (!categoryReady) { duplicateCheck = 'MISSING_CATEGORY_ID'; notes = 'Skipped: no category for "' + (product.Category || '') + '"'; }
  else if (skuFoundInOdoo) { duplicateCheck = 'REJECTED_SKU_EXISTS'; notes = 'SKU "' + sku + '" already exists in Odoo (ID: ' + odooIdFound + ')'; }
  else if (!sku) { duplicateCheck = 'MISSING_SKU'; notes = 'No SKU - will create without Internal Reference'; }
  else { duplicateCheck = 'NEW_CREATE'; notes = 'New product: SKU "' + sku + '" will be created'; }

  return { json: { SKU: sku, Product_Name: productName, Category: product.Category || '', categ_id: categoryReady ? categId : null, category_id_ready: categoryReady, Brand: product.Brand || '', list_price: product.list_price || 0, odoo_id_found: odooIdFound, already_exists: skuFoundInOdoo, duplicate_check: duplicateCheck, Notes: notes, chatId: product.chatId || '' } };
});

const sourceItems = $('Is New Product?').all();
return $input.all().map((createdItem, index) => {
  const created = createdItem.json || {};
  const pairedIndex = createdItem.pairedItem?.item ?? index;
  const source = sourceItems[pairedIndex]?.json || {};
  return { json: { SKU: source.SKU || '', Product_Name: source.Product_Name || '', Category: source.Category || '', Category_ID: source.categ_id || '', Brand: source.Brand || '', Status: 'Created', Odoo_ID: created.id || '', Duplicate_Check: 'NEW_CREATE', Notes: 'Created with Category ID: ' + (source.categ_id || '') } };
});

return $input.all().map(i => {
  const item = i.json || {};
  let status;
  switch (item.duplicate_check) {
    case 'MISSING_CATEGORY_ID': status = 'Skipped - Missing Category ID'; break;
    case 'REJECTED_SKU_EXISTS': status = 'Rejected - SKU Already Exists'; break;
    case 'MISSING_SKU': status = 'Warning - No SKU'; break;
    default: status = 'Skipped';
  }
  return { json: { SKU: item.SKU || '', Product_Name: item.Product_Name || '', Category: item.Category || '', Category_ID: item.categ_id || '', Brand: item.Brand || '', Status: status, Odoo_ID: item.odoo_id_found || '', Duplicate_Check: item.duplicate_check || '', Notes: item.Notes || '' } };
});
